import asyncio
import glob
import inspect
import json
import os
import signal
import sys
import tempfile
import time
from pathlib import Path
from typing import Any, Optional

from ..core import FrameworkAdapter, RunOptions
from ..types import TestCase, TestResult, ResultStatus, TestError


class PytestAdapter(FrameworkAdapter):
    @property
    def name(self) -> str:
        return "pytest"

    def supports(self, framework: str) -> bool:
        return framework == "pytest"

    async def _invoke(self, args: list[str], timeout: Optional[float], env: dict[str, str]) -> dict[str, Any]:
        with tempfile.TemporaryDirectory(prefix="testfn-pytest-") as directory:
            report = Path(directory) / "report.json"
            child_env = {**os.environ, **env, "TESTFN_REPORT": str(report)}
            # Do not inherit pytest options that override discovery/reporting semantics.
            child_env.pop("PYTEST_ADDOPTS", None)
            with tempfile.TemporaryFile() as output:
                process = await asyncio.create_subprocess_exec(
                    sys.executable, "-m", "pytest", "-p", "testfn._pytest_plugin", "-o", "addopts=", *args,
                    stdout=output, stderr=output, env=child_env, start_new_session=os.name == "posix",
                )
                try:
                    await asyncio.wait_for(process.wait(), timeout)
                except (asyncio.TimeoutError, asyncio.CancelledError):
                    try:
                        if os.name == "posix":
                            os.killpg(process.pid, signal.SIGKILL)
                        else:
                            process.kill()
                    except ProcessLookupError:
                        pass
                    await asyncio.shield(process.wait())
                    raise
                output.seek(0, os.SEEK_END)
                output.seek(max(0, output.tell() - 16_384))
                diagnostic = output.read().decode(errors="replace")
            if process.returncode not in (0, 1, 5):
                raise RuntimeError(f"pytest exited {process.returncode}: {diagnostic}")
            try:
                payload = json.loads(report.read_text(encoding="utf-8"))
                if payload["exitstatus"] != process.returncode or not isinstance(payload["results"], list) or not isinstance(payload["collected"], list):
                    raise ValueError("invalid protocol fields")
            except (OSError, ValueError, KeyError, TypeError) as error:
                raise RuntimeError(f"pytest did not produce a valid result report: {diagnostic}") from error
            return payload

    async def discover(self, pattern: list[str]) -> list[TestCase]:
        paths = []
        for value in pattern:
            if not value or value.startswith("-"):
                raise ValueError("Test patterns must be nonempty paths or node IDs, not options")
            if "::" not in value and glob.has_magic(value):
                paths.extend(sorted(glob.glob(value, recursive=True)))
            else:
                paths.append(value)
        if pattern and not paths:
            return []
        payload = await self._invoke(["--collect-only", "-q", "--", *dict.fromkeys(paths)], 60, {})
        return [TestCase.model_validate(row) for row in payload["collected"]]

    async def run(self, tests: list[TestCase], options: RunOptions, on_test_complete: Optional[Any] = None) -> list[TestResult]:
        if len({test.id for test in tests}) != len(tests):
            raise ValueError("Duplicate test IDs")
        semaphore = asyncio.Semaphore(options.parallel)

        async def execute(test: TestCase) -> TestResult:
            async with semaphore:
                start = time.monotonic()
                for attempt in range(options.retries + 1):
                    try:
                        payload = await self._invoke(["-q", "--", test.id], options.timeout, options.env)
