import { rollup } from 'rollup';
import { dts } from 'rollup-plugin-dts';
import { readFile, writeFile, readdir, unlink } from 'node:fs/promises';
import { isAbsolute, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const manifest = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
const declarations = [];
for (const entry of Object.values(manifest.exports)) {
  const bundle = await rollup({
    input: join(root, entry.require.types),
    // Shared package implementations are bundled at runtime. Bundle their actual
    // declarations too: a CJS declaration must not statically import ESM-only
    // declarations. Framework-specific types remain on their opt-in entry point.
    external: id => !id.startsWith('.') && !isAbsolute(id) && !id.startsWith('@superfunctions/'),
    plugins: [dts({ respectExternal: true })],
  });
  try {
    const { output } = await bundle.generate({ format: 'es' });
    if (output.length !== 1 || output[0].type !== 'chunk') throw new Error('Expected one declaration bundle per entry');
    declarations.push([entry.require.types, output[0].code], [entry.import.types, output[0].code]);
  } finally { await bundle.close(); }
}
// Finish all reads before replacing outputs; tsup can share declaration chunks.
async function removeDeclarations(directory) {
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) await removeDeclarations(path);
    else if (/\.d\.(?:ts|mts|cts)$/.test(entry.name)) await unlink(path);
  }
}
await removeDeclarations(join(root, 'dist'));
for (const [path, code] of declarations) await writeFile(join(root, path), code);
console.log(`Bundled declarations for ${declarations.length / 2} entry points`);
EOF
