async function readRegressionIndex(
  repoRoot: string,
  artifactRoot: string,
): Promise<RegressionIndexEntry[]> {
  const diffRoot = path.resolve(repoRoot, artifactRoot, 'diffs');
  const directories = await safeReaddir(diffRoot);
  const regressions: RegressionIndexEntry[] = [];

  for (const directory of directories) {
    if (!directory.isDirectory()) {
      continue;
    }

    const summaryPath = path.resolve(diffRoot, directory.name, 'diff.json');
    try {
      const summary = await readJson<DiffManifest>(summaryPath);
      regressions.push({
        baselineKey: summary.baselineKey,
        summaryPath: toRepoRelative(repoRoot, summaryPath),
        diffPath: path.posix.join(toRepoRelative(repoRoot, path.resolve(diffRoot, directory.name)), 'diff.png'),
        pixelDiffPercent: summary.pixelDiffPercent,
        changedPixels: summary.changedPixels,
        totalPixels: summary.totalPixels,
      });
    } catch {
      continue;
    }
  }

  return regressions.sort((left, right) => left.baselineKey.localeCompare(right.baselineKey));
}

async function readIndexedEvents(
  repoRoot: string,
  relativePath: string | undefined,
  category: CorrelationEventRecord['category'],
  prefix: string,
): Promise<IndexedRuntimeEvent[]> {
  if (!relativePath) {
    return [];
  }

  try {
    const records: IndexedRuntimeEvent[] = [];
    for await (const record of iterateEventSinkFamily(repoRoot, relativePath)) {
      const payload = record.payload;
      const ts = typeof payload.ts === 'string' ? payload.ts : undefined;
      records.push({
        eventId: `${prefix}_${records.length + 1}`,
        category,
        sinkPath: record.relativePath,
        lineNumber: record.lineNumber,
        payload,
        ...(ts ? { ts } : {}),
      });
    }
    return records;
  } catch (error) {
    if (isMissing(error)) {
      return [];
    }

    throw error;
  }
}

async function resolveTracePath(
  repoRoot: string,
  tracePath: string | null,
): Promise<string | null> {
  if (!tracePath) {
    return null;
  }

  try {
    await access(path.resolve(repoRoot, tracePath));
    return tracePath;
  } catch {
    return null;
  }
}

async function safeReaddir(absolutePath: string) {
  try {
    return await readdir(absolutePath, { withFileTypes: true });
  } catch (error) {
    if (isMissing(error)) {
      return [];
    }

    throw error;
  }
}

function toCorrelationCheckpoint(checkpoint: CheckpointIndexEntry): CorrelationCheckpointRecord {
  return {
    checkpointId: checkpoint.checkpointId,
    name: checkpoint.name,
    manifestPath: checkpoint.manifestPath,
    artifactPaths: checkpoint.artifacts.map((artifact: CheckpointManifest['artifacts'][number]) => artifact.path),
    createdAt: checkpoint.createdAt,
    url: checkpoint.url,
  };
}

function toRepoRelative(repoRoot: string, absolutePath: string): string {
  return path.relative(repoRoot, absolutePath).split(path.sep).join(path.posix.sep);
}

async function readJson<TValue>(absolutePath: string): Promise<TValue> {
  return JSON.parse(await readFile(absolutePath, 'utf8')) as TValue;
}

function isMissing(error: unknown): boolean {
  return Boolean(
    error &&
      typeof error === 'object' &&
      'code' in error &&
      (error as { code?: string }).code === 'ENOENT',
  );
}

function dedupeBySignature<TValue>(
  values: TValue[],
  signature: (value: TValue) => string,
): TValue[] {
  const seen = new Set<string>();
  return values.filter((value) => {
    const next = signature(value);
    if (seen.has(next)) {
      return false;
    }

    seen.add(next);
    return true;
  });
}
# Streaming event reads

Event delta counting previously loaded and retained every event payload before counting. A 160,000-record fixture exceeded a 64 MiB V8 heap and aborted with the prior delta implementation. The same fixture now completes under that heap limit with all 160,000 errors counted.

The storage async iterator reads 64 KiB chunks, yields one parsed record at a time, preserves physical line numbers and numeric rollover order, and closes actual file handles on completion, early return and failure. Each segment scan is bounded to the size observed when reading starts; appends become visible on a subsequent scan. Missing anchors preserve existing caller behavior. Missing rollover indexes, ambiguous numeric aliases, a disappeared rollover, a truncated segment or invalid JSON fail explicitly rather than returning partial evidence. Errors identify the relative segment and line without including raw payloads.

A configurable maxRecordBytes bounds an encoded record (default 64 MiB, excluding newline); exceeding it raises E_STORAGE_CAP_EXCEEDED without truncation. The compatibility collector remains available. Action delta counts consume the iterator directly. Reports construct their required output index directly without a second temporary array of stored records.

Validation: Node 22 unified 135 tests across 30 files and strict TypeScript checks pass. Eleven new regressions cover UTF-8 crossing chunk boundaries, CRLF/blank/final lines, exact byte limits, malformed records, early file-handle closure, disappearance/truncation, append boundaries, missing/ambiguous rollover indexes and counting across rollover. All JSON values accepted by the existing sink writer remain readable. Existing storage-to-MCP/report provenance coverage passes. Run `npm run test:event-streaming --workspace=@probefn/workspace` for the actual constrained-heap acceptance; its temporary fixture is removed on success/failure.

Limits: directory enumeration retains the segment names, and each parsed record requires memory proportional to its bounded size. This is a live append-only scan, not a retained cross-file snapshot or protection against replacement. The compatibility collector and final report document still retain output-sized memory. The three MCP event tools subsequently gained bounded pages; see `mcp-event-pagination-readiness.md` for their cursor contract and validation. This does not fix durable per-run disk accounting, external browser artifact accounting, Firefox launch, Windows process ownership, packaging, hosted or performance/accessibility gates.
