export async function authorize(
  config: AuthorizeConfig,
  req: IncomingMessage,
  input: { dataset: string; type: string; action: CmsfnAction }
): Promise<boolean> {
  const getRoles = config.getRolesForSubject;
  if (!getRoles) {
    return false;
  }
