            return json(receipt(value), 201);
          });
        } catch (error) {
          if (attempt === 7) throw error;
          await new Promise(resolve => setTimeout(resolve, attempt * 5));
        }
      }
      throw new Error('Survey storage unavailable');
    } },
  ];
}
